const translateText=(value:string,lang:Lang)=>{
 if(lang==='fr') return value
 const dict={...TRANSLATIONS[lang],...EXTRA_TRANSLATIONS[lang]}
 let out=value
 const exact=dict[value.trim()]
 if(exact) return value.replace(value.trim(),exact)
 for(const [fr,tr] of Object.entries(dict)){
  if(out.includes(fr)) out=out.split(fr).join(tr)
 }
 return out
}
function LanguageLayer({lang}:{lang:Lang}){
 useEffect(()=>{
  document.documentElement.lang=lang
  const apply=()=>{
   document.querySelectorAll('body *').forEach(el=>{
    if(el instanceof HTMLElement && !el.closest('.lang-switch')){
      el.childNodes.forEach(n=>{if(n.nodeType===Node.TEXT_NODE&&n.textContent){const v=translateText(n.textContent,lang);if(v!==n.textContent)n.textContent=v}})
      if((el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) && el.placeholder){
       const p=translateText(el.placeholder,lang); if(p!==el.placeholder) el.placeholder=p
      }
      for(const attr of ['aria-label','title']){
       const raw=el.getAttribute(attr); if(raw){const tr=translateText(raw,lang);if(tr!==raw)el.setAttribute(attr,tr)}
      }
    }
   })
  }
  apply()
  const o=new MutationObserver(apply);o.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']})
  return()=>o.disconnect()
 },[lang])
 return null
}

